import { useDirection } from '@base-ui/react/direction-provider'
import {
  type ComponentProps,
  type CSSProperties,
  type ReactNode,
  type RefObject,
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  useSyncExternalStore,
} from 'react'
import {
  animate,
  AnimatePresence,
  cancelFrame,
  frame,
  motion,
  MotionConfig,
  useIsPresent,
  useMotionValue,
  usePresenceData,
  useReducedMotion,
} from 'motion/react'

import { ALERT_MARKS, type AlertTone } from '@/components/ui/alert'
import { Button } from '@/components/ui/button'
import { StatusBadge } from '@/components/ui/spinner'
import { joinsLetters } from '@/lib/joined-script'
import { dissolve } from '@/lib/smoky-dissolve'
import { cn } from '@/lib/utils'

const EVENT = 'kobra:toast'
const DISMISS = 'kobra:toast-dismiss'
const LIFETIME = 2400

const DETAIL_LIFETIME = 4000

const ACTION_LIFETIME = 6000
const GAP = 8

const PEEK = 10
const SHRINK = 0.03
const DEPTH = 3
const FADE = 0.15
const REACH = 10
const SWIPE = 44
const FLICK = 380
const MORPH = { type: 'spring', duration: 0.3, bounce: 0 } as const
const EXIT = { type: 'spring', duration: 0.2, bounce: 0 } as const

export const LINE_HEIGHT = 36

const CARD_WIDTH = 340

export type ToastSide = 'top' | 'bottom'

export type ToastAlign = 'start' | 'center' | 'end' | 'left' | 'right'
export type ToastPosition = `${ToastSide}-${ToastAlign}`
export const toastPositions = [
  'top-start',
  'top-center',
  'top-end',
  'bottom-start',
  'bottom-center',
  'bottom-end',
] as const satisfies readonly ToastPosition[]

type ToastEdge = 'start' | 'center' | 'end'

const JUSTIFY: Record<ToastEdge, string> = {
  start: 'justify-start',
  center: 'justify-center',
  end: 'justify-end',
}

export type ToastState = 'pending' | AlertTone
export type ToastAction = { label: string; run: () => void }
export type ToastInput = {
  id?: string
  message: string

  description?: string
  state?: ToastState
  action?: ToastAction
  lifetime?: number
}
export type Note = ToastInput & { id: string }
export type ToastClock = { waits: Map<string, number>; since: number | null }
export type StackSlot = { y: number; scale: number; opacity: number }
export type StackCard = {
  id: string
  render: (behind: boolean) => ReactNode
}

let nextId = 0

export function toast(input: string | ToastInput) {
  const detail = typeof input === 'string' ? { message: input } : input
  window.dispatchEvent(
    new CustomEvent(EVENT, {
      detail: { ...detail, id: detail.id ?? `toast-${++nextId}` },
    }),
  )
}

export function dismissToast(id: string) {
  window.dispatchEvent(new CustomEvent(DISMISS, { detail: id }))
}

export function upsertToast(notes: readonly Note[], note: Note): Note[] {
  const index = notes.findIndex((item) => item.id === note.id)
  return index === -1 ? [note, ...notes] : notes.map((item, at) => (at === index ? note : item))
}

export function dismissDelay(
  state: ToastState | undefined,
  hasAction: boolean,
  lifetime?: number,
  hasDetail = false,
): number | null {
  if (state === 'pending') return null
  if (lifetime !== undefined) return lifetime
  return hasAction ? ACTION_LIFETIME : hasDetail ? DETAIL_LIFETIME : LIFETIME
}

export function tick(clock: ToastClock, at: number) {
  if (clock.since === null) return

  const spent = at - clock.since
  clock.since = at
  for (const [id, left] of clock.waits) clock.waits.set(id, left - spent)
}

export function pileSlot(index: number): StackSlot {
  const depth = Math.min(index, DEPTH - 1)
  return {
    y: depth * PEEK,
    scale: 1 - depth * SHRINK,
    opacity: index < DEPTH ? 1 - depth * FADE : 0,
  }
}

export function fanSlot(index: number, heights: readonly number[]): StackSlot {
  let y = 0
  for (let at = 0; at < index; at++) y += (heights[at] ?? LINE_HEIGHT) + GAP
  return { y, scale: 1, opacity: 1 }
}

const TONE_INK: Record<Exclude<AlertTone, 'success'>, string> = {
  error: 'text-error',
  warning: 'text-warning',
  info: 'text-info',
}

const BADGE_SIZE = { '--check-size': '16px' } as CSSProperties

function ToastGlyph({ state }: { state: ToastState }) {
  switch (state) {

    case 'pending':
    case 'success':
      return (

        <span className="flex" style={BADGE_SIZE}>
          <StatusBadge state={state === 'success' ? 'done' : 'loading'} />
        </span>
      )
    case 'error':
    case 'warning':
    case 'info': {
      const Mark = ALERT_MARKS[state]

      return (
        <Mark
          className={cn('shrink-0', state === 'error' ? 'size-5' : 'size-4', TONE_INK[state])}
          aria-hidden
        />
      )
    }
    default: {
      const exhaustive: never = state
      return exhaustive
    }
  }
}

const GLYPH_POP = {
  initial: { opacity: 0, scale: 0.25, filter: 'blur(4px)' },
  animate: { opacity: 1, scale: 1, filter: 'blur(0px)' },
  exit: { opacity: 0, scale: 0.25, filter: 'blur(4px)', transition: EXIT },
} as const

const REVEAL = {

  delay: 0.04,

  sweep: 0.16,
  step: 0.02,
  duration: 0.24,

  after: 0.06,
  ease: [0.23, 1, 0.32, 1],
} as const

const graphemes = new Intl.Segmenter(undefined, { granularity: 'grapheme' })

function RevealText({
  text,
  words = false,
  after = 0,
}: {
  text: string
  words?: boolean
  after?: number
}) {
  const reduceMotion = useReducedMotion()

  const parts =
    words || joinsLetters(text)
      ? text.split(/(\s+)/).filter(Boolean)
      : [...graphemes.segment(text)].map(({ segment }) => segment)
  const step = Math.min(REVEAL.step, REVEAL.sweep / Math.max(parts.length - 1, 1))

  return (
    <>
      <span className="sr-only">{text}</span>
      <span aria-hidden>
        {parts.map((part, index) => (
          <motion.span
            key={index}
            initial={reduceMotion ? false : { opacity: 0, filter: 'blur(4px)' }}
            animate={{ opacity: 1, filter: 'blur(0px)' }}
            transition={{
              duration: REVEAL.duration,
              ease: REVEAL.ease,
              delay: REVEAL.delay + after + index * step,
            }}
          >
            {part}
          </motion.span>
        ))}
      </span>
    </>
  )
}

function ToastLine({
  message,
  reveal = false,
  from = 0,
}: {
  message: string
  reveal?: boolean
  from?: number
}) {

  const [revealed] = useState(reveal)
  const fading = !useIsPresent()
  return (
    <motion.div
      initial={{ width: from }}
      animate={{ width: 'auto' }}
      exit={{ opacity: 0, filter: 'blur(4px)', transition: EXIT }}
      transition={MORPH}
      className={cn('flex items-center overflow-hidden', fading && 'absolute inset-y-0 start-0')}
    >
      <span className="w-max max-w-lg shrink-0 truncate">
        {revealed ? <RevealText text={message} /> : message}
      </span>
    </motion.div>
  )
}

function ToastDetail({ text, reveal, from }: { text: string; reveal: boolean; from: number }) {
  const [revealed] = useState(reveal)
  const present = useIsPresent()
  const swapping = usePresenceData() === true
  const fading = !present && swapping
  return (
    <motion.div
      initial={{
        height: from,
        opacity: revealed ? 1 : 0,
        filter: revealed ? 'blur(0px)' : 'blur(4px)',
      }}
      animate={{ height: 'auto', opacity: 1, filter: 'blur(0px)' }}
      exit="leave"
      variants={{
        leave: (swap: boolean) =>
          swap
            ? { opacity: 0, filter: 'blur(4px)', transition: EXIT }
            : { height: 0, opacity: 0, filter: 'blur(4px)' },
      }}
      transition={MORPH}
      className={cn('overflow-hidden', fading && 'absolute inset-x-0 top-0')}
    >

      <p className="pb-0.75 text-pretty text-muted-foreground">
        {revealed ? <RevealText text={text} words after={REVEAL.after} /> : text}
      </p>
    </motion.div>
  )
}

const glyphKey = (state: ToastState) =>
  state === 'pending' || state === 'success' ? 'badge' : state

function ToastPill({
  state,
  message,
  description,
  action,
  onAction,
  onDismiss,
  behind,
}: {
  state?: ToastState
  message: string
  description?: string
  action?: ToastAction
  onAction: () => void
  onDismiss: () => void
  behind: boolean
}) {
  const pill = useRef<HTMLDivElement>(null)
  const lines = useRef<HTMLDivElement>(null)
  const details = useRef<HTMLDivElement>(null)
  const [lineWidth, setLineWidth] = useState(0)
  const [detailHeight, setDetailHeight] = useState(0)
  useLayoutEffect(() => {
    const line = lines.current
    const detail = details.current
    if (!line || !detail) return
    const observer = new ResizeObserver(() => {
      setLineWidth(line.offsetWidth)
      setDetailHeight(detail.offsetHeight)
    })
    observer.observe(line)
    observer.observe(detail)
    return () => observer.disconnect()
  }, [])

  const [last, setLast] = useState({ message, state, description })
  const [reveal, setReveal] = useState(false)
  const [revealDetail, setRevealDetail] = useState(false)
  const [detailSwap, setDetailSwap] = useState(false)
  if (last.message !== message || last.state !== state || last.description !== description) {
    setReveal(last.message !== message)
    setRevealDetail(last.description !== description)
    setDetailSwap(Boolean(last.description) && Boolean(description))
    setLast({ message, state, description })
  }

  return (
    <motion.div
      ref={pill}

      style={{ borderRadius: LINE_HEIGHT / 2 }}
      drag={behind ? false : true}
      dragSnapToOrigin
      dragElastic={0.6}
      dragMomentum={false}
      dragTransition={{ bounceStiffness: 520, bounceDamping: 42 }}
      onDragEnd={(_, info) => {
        const far = Math.hypot(info.offset.x, info.offset.y) > SWIPE
        const fast = Math.hypot(info.velocity.x, info.velocity.y) > FLICK
        if (!far && !fast) return

        if (pill.current) dissolve(pill.current, { onComplete: onDismiss })
        else onDismiss()
      }}
      className={cn(
        'toast-pill relative flex max-w-lg overflow-hidden bg-popover/80 text-sm text-foreground backdrop-blur-md',
        behind ? 'pointer-events-none' : 'pointer-events-auto cursor-grab active:cursor-grabbing',

        action ? 'pe-2' : 'pe-4',
        state ? 'ps-3' : 'ps-4',

        description && 'pt-0.5',
      )}
    >
      <motion.div
        animate={{ opacity: behind ? 0 : 1 }}
        transition={MORPH}

        className="grid min-w-max grid-cols-[auto_minmax(0,1fr)_auto] items-center"
      >

        <div className="col-start-1 row-start-1 flex">
          <AnimatePresence initial={false}>
            {state ? (
              <motion.div
                key="glyph"
                initial={{ width: 0 }}
                animate={{ width: 'auto' }}
                exit={{ width: 0 }}
                transition={MORPH}

                className="flex justify-end"
              >

                <div className="flex w-max items-center pe-3">

                  <AnimatePresence initial={false} mode="popLayout">
                    <motion.span
                      key={glyphKey(state)}
                      {...GLYPH_POP}
                      transition={MORPH}
                      className="flex size-4 shrink-0 items-center justify-center"
                    >
                      <ToastGlyph state={state} />
                    </motion.span>
                  </AnimatePresence>
                </div>
              </motion.div>
            ) : null}
          </AnimatePresence>
        </div>

        <div
          ref={lines}
          className={cn(
            'relative col-start-2 row-start-1 flex h-9 items-center justify-self-start',
            description && 'font-bold',
          )}
        >
          <AnimatePresence initial={false}>
            <ToastLine key={message} message={message} reveal={reveal} from={lineWidth} />
          </AnimatePresence>
        </div>

        <div className="col-start-3 row-start-1 flex">
          <AnimatePresence initial={false}>
            {action ? (
              <motion.div
                key="action"
                initial={{ width: 0 }}
                animate={{ width: 'auto' }}
                exit={{ width: 0 }}
                transition={MORPH}

                className="-my-1 -me-1 flex items-center overflow-hidden rounded-full py-1 pe-1"
              >
                <div className="w-max ps-7">
                  <Button type="button" size="sm" onClick={onAction} className="h-7 rounded-full">
                    {action.label}
                  </Button>
                </div>
              </motion.div>
            ) : null}
          </AnimatePresence>
        </div>

        <div
          ref={details}
          className={cn(
            'toast-detail relative -top-1.5 col-span-2 col-start-2 row-start-2 w-0 min-w-full',
            action ? 'pe-2' : 'pe-0',
          )}
        >
          <AnimatePresence initial={false} custom={detailSwap}>
            {description ? (
              <ToastDetail
                key={description}
                text={description}
                reveal={revealDetail}
                from={detailSwap ? detailHeight : 0}
              />
            ) : null}
          </AnimatePresence>
        </div>

        <motion.div
          aria-hidden
          initial={false}
          animate={{ width: description ? CARD_WIDTH - (state ? 12 : 16) - (action ? 8 : 16) : 0 }}
          transition={MORPH}
          className="col-span-3 col-start-1 row-start-3"
        />
      </motion.div>
    </motion.div>
  )
}

function sameBoxes(
  first: Record<string, { width: number; height: number }>,
  second: Record<string, { width: number; height: number }>,
) {
  const ids = Object.keys(second)
  return (
    ids.length === Object.keys(first).length &&
    ids.every(
      (id) => first[id]?.width === second[id]?.width && first[id]?.height === second[id]?.height,
    )
  )
}

type Side = 'maxWidth' | 'maxHeight'

function useCap(box: RefObject<HTMLDivElement | null>, side: Side, cap: number | null) {
  const limit = useMotionValue<number | string>('none')

  useLayoutEffect(() => {
    const element = box.current
    if (!element) return

    const natural = () => {
      const held = element.style[side]
      element.style[side] = ''
      const size = side === 'maxWidth' ? element.offsetWidth : element.offsetHeight
      element.style[side] = held
      return size
    }
    if (cap === null) {
      if (limit.get() === 'none') return
      const release = () => limit.set('none')
      const controls = animate(limit, natural(), {
        ...MORPH,

        onComplete: () => frame.update(release),
      })
      return () => {
        controls.stop()
        cancelFrame(release)
      }
    }

    if (limit.get() === 'none') limit.set(natural())
    const controls = animate(limit, cap, MORPH)
    return () => controls.stop()
  }, [box, side, cap, limit])

  return limit
}

function DeckCap({
  width,
  height,
  ref,
  children,
}: {
  width: number | null
  height: number | null
  ref: (element: HTMLDivElement | null) => void
  children: ReactNode
}) {
  const box = useRef<HTMLDivElement | null>(null)
  const maxWidth = useCap(box, 'maxWidth', width)
  const maxHeight = useCap(box, 'maxHeight', height)

  return (
    <motion.div
      ref={(element) => {
        box.current = element
        ref(element)
      }}
      style={{ maxWidth, maxHeight }}

      className="relative flex flex-col"
    >
      {children}
    </motion.div>
  )
}

function DeckSlot({
  layer,
  style,
  ...motionProps
}: ComponentProps<typeof motion.div> & { layer: number }) {
  const present = useIsPresent()
  return <motion.div {...motionProps} style={{ ...style, zIndex: present ? layer : 0 }} />
}

function ToastStack({
  cards,
  onOpen,
  position,
}: {
  cards: StackCard[]
  onOpen: (open: boolean) => void
  position: ToastPosition
}) {
  const [pointing, setPointing] = useState(false)
  const [focused, setFocused] = useState(false)
  const [holding, setHolding] = useState(false)
  const [boxes, setBoxes] = useState<Record<string, { width: number; height: number }>>({})
  const measured = useRef(new Map<string, HTMLElement>())
  const root = useRef<HTMLDivElement>(null)
  const textDirection = useDirection()

  const open = pointing || focused || holding
  const piled = cards.length > 1 && !open

  useEffect(() => onOpen(open), [onOpen, open])

  useEffect(() => {
    if (!holding) return
    const release = () => setHolding(false)

    const check = (event: PointerEvent) => {
      if (event.buttons === 0) release()
    }
    window.addEventListener('pointerup', release)
    window.addEventListener('pointercancel', release)
    window.addEventListener('pointermove', check)
    return () => {
      window.removeEventListener('pointerup', release)
      window.removeEventListener('pointercancel', release)
      window.removeEventListener('pointermove', check)
    }
  }, [holding])

  const at = useRef<{ x: number; y: number } | null>(null)
  const overCards = useCallback(
    () =>
      at.current !== null &&
      [...measured.current.values()].some((element) => {
        const box = element.getBoundingClientRect()
        return (
          at.current!.x >= box.left - REACH &&
          at.current!.x <= box.right + REACH &&
          at.current!.y >= box.top - REACH &&
          at.current!.y <= box.bottom + REACH
        )
      }),
    [],
  )

  useEffect(() => {
    const onMove = (event: PointerEvent) => {
      at.current = { x: event.clientX, y: event.clientY }
      setPointing(overCards())
    }

    const onLeave = () => {
      at.current = null
      setPointing(false)
    }

    window.addEventListener('pointermove', onMove)
    document.documentElement.addEventListener('pointerleave', onLeave)
    return () => {
      window.removeEventListener('pointermove', onMove)
      document.documentElement.removeEventListener('pointerleave', onLeave)
    }
  }, [overCards])

  useEffect(() => {
    if (!pointing) return
    let frame = requestAnimationFrame(function check() {
      if (!overCards()) {
        setPointing(false)
        return
      }
      frame = requestAnimationFrame(check)
    })
    return () => cancelAnimationFrame(frame)
  }, [pointing, overCards])

  useEffect(() => {
    if (!focused) return
    let frame = requestAnimationFrame(function check() {
      if (!root.current?.contains(document.activeElement)) {
        setFocused(false)
        return
      }
      frame = requestAnimationFrame(check)
    })
    return () => cancelAnimationFrame(frame)
  }, [focused])

  const measure = useCallback(() => {
    const next: Record<string, { width: number; height: number }> = {}
    for (const [id, element] of measured.current) {

      const { maxWidth, maxHeight } = element.style
      element.style.maxWidth = ''
      element.style.maxHeight = ''
      next[id] = { width: element.offsetWidth, height: element.offsetHeight }
      element.style.maxWidth = maxWidth
      element.style.maxHeight = maxHeight
    }
    setBoxes((current) => (sameBoxes(current, next) ? current : next))
  }, [])

  useLayoutEffect(measure, [cards, measure])

  const sizes = useRef<ResizeObserver | null>(null)
  useEffect(() => {
    const observer = new ResizeObserver(measure)
    for (const element of measured.current.values()) observer.observe(element)
    sizes.current = observer
    return () => observer.disconnect()
  }, [measure])

  const heights = cards.map((card) => boxes[card.id]?.height ?? LINE_HEIGHT)
  const deck = cards[0] ? boxes[cards[0].id] : undefined
  const [side, align] = position.split('-') as [ToastSide, ToastAlign]
  const rtl = textDirection === 'rtl'
  const edge: ToastEdge =
    align === 'left' ? (rtl ? 'end' : 'start') : align === 'right' ? (rtl ? 'start' : 'end') : align

  const corner = edge === 'center' ? 'center' : (edge === 'start') !== rtl ? 'left' : 'right'

  const fall = side === 'top' ? 1 : -1

  return (
    <motion.div
      ref={root}
      aria-live="polite"
      onPointerDown={() => setHolding(true)}
      onFocus={() => setFocused(true)}
      onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget)) setFocused(false)
      }}
      className={cn(
        'pointer-events-none fixed inset-x-0 z-100',
        side === 'top' ? 'top-4' : 'bottom-4',
      )}
    >
      <AnimatePresence initial={false}>
        {cards.map((card, index) => {
          const slot = piled ? pileSlot(index) : fanSlot(index, heights)

          const drop =
            piled && index > 0
              ? Math.max(0, (heights[0] ?? LINE_HEIGHT) - (heights[index] ?? LINE_HEIGHT))
              : 0
          const y = (slot.y + drop) * fall
          const from = (slot.y + drop - 8) * fall
          return (
            <DeckSlot
              key={card.id}
              layer={cards.length - index}
              style={{

                transformOrigin: `${side} ${corner}`,
              }}
              initial={{ opacity: 0, y: from, scale: slot.scale * 0.98 }}
              animate={{ opacity: slot.opacity, y, scale: slot.scale }}
              exit={{ opacity: 0, y: from, scale: slot.scale * 0.96, transition: EXIT }}
              transition={MORPH}
              className={cn(
                'absolute inset-x-0 flex px-4',
                side === 'top' ? 'top-0' : 'bottom-0',
                JUSTIFY[edge],
              )}
              aria-hidden={slot.opacity === 0 || undefined}
            >
              <DeckCap
                width={piled && index > 0 ? (deck?.width ?? null) : null}
                height={piled && index > 0 ? (deck?.height ?? null) : null}
                ref={(element) => {
                  if (element) {
                    measured.current.set(card.id, element)
                    sizes.current?.observe(element)
                    return
                  }
                  const gone = measured.current.get(card.id)
                  if (gone) sizes.current?.unobserve(gone)
                  measured.current.delete(card.id)
                }}
              >
                {card.render(piled && index > 0)}
              </DeckCap>
            </DeckSlot>
          )
        })}
      </AnimatePresence>
    </motion.div>
  )
}

function subscribeVisibility(onChange: () => void) {
  document.addEventListener('visibilitychange', onChange)
  return () => document.removeEventListener('visibilitychange', onChange)
}

function useDocumentHidden() {
  return useSyncExternalStore(
    subscribeVisibility,
    () => document.hidden,
    () => false,
  )
}

export function Toasts({ position = 'top-center' }: { position?: ToastPosition }) {
  const [notes, setNotes] = useState<Note[]>([])
  const [reading, setReading] = useState(false)
  const hidden = useDocumentHidden()

  const paused = reading || hidden
  const clock = useRef<ToastClock>({ waits: new Map(), since: null })

  const issued = useRef<string | null>(null)

  useEffect(() => {
    clock.current.since = performance.now()

    const onToast = (event: Event) => {
      const note = (event as CustomEvent<Note>).detail
      issued.current = note.id
      setNotes((current) => upsertToast(current, note))
      tick(clock.current, performance.now())
      const delay = dismissDelay(
        note.state,
        note.action !== undefined,
        note.lifetime,
        note.description !== undefined,
      )
      if (delay === null) clock.current.waits.delete(note.id)
      else clock.current.waits.set(note.id, delay)
    }
    const onDismiss = (event: Event) => {
      const id = (event as CustomEvent<string>).detail
      clock.current.waits.delete(id)
      setNotes((current) => current.filter((note) => note.id !== id))
    }

    window.addEventListener(EVENT, onToast)
    window.addEventListener(DISMISS, onDismiss)
    return () => {
      window.removeEventListener(EVENT, onToast)
      window.removeEventListener(DISMISS, onDismiss)
    }
  }, [])

  useEffect(() => {
    tick(clock.current, performance.now())
    clock.current.since = paused ? null : performance.now()
  }, [paused])

  useEffect(() => {
    if (paused) return

    tick(clock.current, performance.now())
    const waits = [...clock.current.waits.values()]
    if (waits.length === 0) return

    const timer = window.setTimeout(
      () => {
        tick(clock.current, performance.now())
        const expired = new Set<string>()
        for (const [id, left] of clock.current.waits) {
          if (left <= 0) expired.add(id)
        }
        for (const id of expired) clock.current.waits.delete(id)
        setNotes((current) => current.filter((note) => !expired.has(note.id)))
      },
      Math.max(0, Math.min(...waits)),
    )
    return () => window.clearTimeout(timer)
  }, [notes, paused])

  return (
    <MotionConfig reducedMotion="user">
      <ToastStack
        position={position}
        onOpen={setReading}
        cards={notes.map((note) => {
          const drop = () => {
            clock.current.waits.delete(note.id)
            setNotes((current) => current.filter((item) => item.id !== note.id))
          }

          const act = () => {
            issued.current = null
            note.action?.run()
            if (issued.current !== note.id) drop()
          }
          return {
            id: note.id,
            render: (behind) => (
              <ToastPill
                state={note.state}
                message={note.message}
                description={note.description}
                action={note.action}
                onAction={act}
                onDismiss={drop}
                behind={behind}
              />
            ),
          }
        })}
      />
    </MotionConfig>
  )
}

const JOINED =
  /[\p{Script=Arabic}\p{Script=Syriac}\p{Script=Nko}\p{Script=Mongolian}\p{Script=Adlam}\p{Script=Hanifi_Rohingya}\p{Script=Mandaic}]/u

export const joinsLetters = (text: string) => JOINED.test(text)

function readNum(name: string, fallback: number): number {
  const raw = getComputedStyle(document.documentElement).getPropertyValue(name).trim()
  if (!raw) return fallback
  if (raw.endsWith('ms')) return Number.parseFloat(raw)
  if (raw.endsWith('s')) return Number.parseFloat(raw) * 1000
  const n = Number.parseFloat(raw)
  return Number.isNaN(n) ? fallback : n
}

function readStr(name: string): string {
  return getComputedStyle(document.documentElement).getPropertyValue(name).trim()
}

function makeEaseSampler(raw: string): (x: number) => number {
  const kw: Record<string, [number, number, number, number]> = {
    linear: [0, 0, 1, 1],
    ease: [0.25, 0.1, 0.25, 1],
    'ease-in': [0.42, 0, 1, 1],
    'ease-out': [0, 0, 0.58, 1],
    'ease-in-out': [0.42, 0, 0.58, 1],
  }
  let c = kw[raw.trim()]
  if (!c) {
    const m = /cubic-bezier\(\s*([-\d.]+),\s*([-\d.]+),\s*([-\d.]+),\s*([-\d.]+)\s*\)/.exec(raw)
    if (m) c = [Number(m[1]), Number(m[2]), Number(m[3]), Number(m[4])]
  }
  const [x1, y1, x2, y2] = c ?? kw.ease!
  const cx = 3 * x1
  const bx = 3 * (x2 - x1) - cx
  const ax = 1 - cx - bx
  const cy = 3 * y1
  const by = 3 * (y2 - y1) - cy
  const ay = 1 - cy - by
  const sx = (t: number) => ((ax * t + bx) * t + cx) * t
  const dxf = (t: number) => (3 * ax * t + 2 * bx) * t + cx
  const sy = (t: number) => ((ay * t + by) * t + cy) * t
  return (x) => {
    if (x <= 0) return 0
    if (x >= 1) return 1
    let t = x
    for (let i = 0; i < 6; i++) {
      const e = sx(t) - x
      if (Math.abs(e) < 1e-4) break
      const d = dxf(t)
      if (Math.abs(d) < 1e-6) break
      t -= e / d
    }
    return sy(t)
  }
}

const TRANSPARENT = /^rgba?\(.*,\s*0\)$/

function radiusOf(style: CSSStyleDeclaration, w: number, h: number): number {
  const raw = style.borderTopLeftRadius
  const value = raw.endsWith('%')
    ? (Number.parseFloat(raw) / 100) * Math.min(w, h)
    : Number.parseFloat(raw)
  return Math.min(Number.isNaN(value) ? 0 : value, Math.min(w, h) / 2)
}

function paintSvg(ctx: CanvasRenderingContext2D, svg: SVGSVGElement, x: number, y: number) {
  const box = svg.getBoundingClientRect()
  const view = svg.viewBox.baseVal
  const vw = view.width || box.width
  const vh = view.height || box.height
  if (!vw || !vh) return
  ctx.save()
  ctx.translate(x, y)
  ctx.scale(box.width / vw, box.height / vh)
  ctx.translate(-view.x, -view.y)
  for (const path of svg.querySelectorAll('path')) {
    const d = path.getAttribute('d')
    if (!d) continue
    const style = getComputedStyle(path)
    const shape = new Path2D(d)
    if (style.fill && style.fill !== 'none' && !TRANSPARENT.test(style.fill)) {
      ctx.fillStyle = style.fill
      ctx.fill(shape)
    }
    if (style.stroke && style.stroke !== 'none' && !TRANSPARENT.test(style.stroke)) {
      ctx.strokeStyle = style.stroke
      ctx.lineWidth = Number.parseFloat(style.strokeWidth) || 1
      ctx.lineCap = style.strokeLinecap as CanvasLineCap
      ctx.lineJoin = style.strokeLinejoin as CanvasLineJoin

      const dash = style.strokeDasharray
      if (dash && dash !== 'none') {
        ctx.setLineDash(
          dash
            .split(/[\s,]+/)
            .map(Number.parseFloat)
            .filter(Number.isFinite),
        )
        ctx.lineDashOffset = Number.parseFloat(style.strokeDashoffset) || 0
      }
      ctx.stroke(shape)
      ctx.setLineDash([])
    }
  }
  ctx.restore()
}

function fillBox(
  ctx: CanvasRenderingContext2D,
  style: CSSStyleDeclaration,
  x: number,
  y: number,
  w: number,
  h: number,
) {
  const r = radiusOf(style, w, h)
  if (!TRANSPARENT.test(style.backgroundColor) && style.backgroundColor !== 'transparent') {
    ctx.beginPath()
    ctx.roundRect(x, y, w, h, r)
    ctx.fillStyle = style.backgroundColor
    ctx.fill()
  }
  const bw = Number.parseFloat(style.borderTopWidth)
  if (bw > 0 && !TRANSPARENT.test(style.borderTopColor)) {
    ctx.beginPath()
    ctx.roundRect(x + bw / 2, y + bw / 2, w - bw, h - bw, Math.max(0, r - bw / 2))
    ctx.strokeStyle = style.borderTopColor
    ctx.lineWidth = bw
    ctx.stroke()
  }
}

function paintPseudo(
  ctx: CanvasRenderingContext2D,
  node: Element,
  which: '::before' | '::after',
  x: number,
  y: number,
) {
  const style = getComputedStyle(node, which)
  if (style.content === 'none' || style.position !== 'absolute') return
  const w = Number.parseFloat(style.width)
  const h = Number.parseFloat(style.height)
  const top = Number.parseFloat(style.top)
  const left = Number.parseFloat(style.left)
  if (![w, h, top, left].every(Number.isFinite)) return
  fillBox(ctx, style, x + left, y + top, w, h)
}

function paint(ctx: CanvasRenderingContext2D, root: Element, ox: number, oy: number) {
  const origin = root.getBoundingClientRect()
  const walk = (node: Element) => {
    const style = getComputedStyle(node)
    const alpha = Number(style.opacity)
    if (style.visibility === 'hidden' || style.display === 'none' || alpha === 0) return
    const box = node.getBoundingClientRect()
    if (box.width === 0 || box.height === 0) return

    if (style.overflow === 'hidden' && box.width <= 1 && box.height <= 1) return
    const x = box.left - origin.left + ox
    const y = box.top - origin.top + oy

    ctx.save()
    ctx.globalAlpha = Number.isNaN(alpha) ? 1 : alpha
    if (node instanceof SVGSVGElement) {
      paintSvg(ctx, node, x, y)
      ctx.restore()
      return
    }

    fillBox(ctx, style, x, y, box.width, box.height)
    paintPseudo(ctx, node, '::before', x, y)

    ctx.fillStyle = style.color
    ctx.font = `${style.fontStyle} ${style.fontWeight} ${style.fontSize} ${style.fontFamily}`
    ctx.textBaseline = 'middle'

    ctx.direction = style.direction === 'rtl' ? 'rtl' : 'ltr'
    ctx.textAlign = 'left'
    for (const child of node.childNodes) {
      if (child.nodeType !== Node.TEXT_NODE || !child.textContent?.trim()) continue

      const range = document.createRange()
      range.selectNodeContents(child)
      if (range.getClientRects().length > 1) {

        for (const word of child.textContent.matchAll(/\S+/g)) {
          range.setStart(child, word.index)
          range.setEnd(child, word.index + word[0].length)
          const at = range.getBoundingClientRect()
          ctx.fillText(
            word[0],
            at.left - origin.left + ox,
            at.top - origin.top + oy + at.height / 2,
          )
        }
        continue
      }
      const line = range.getBoundingClientRect()
      ctx.fillText(
        child.textContent,
        line.left - origin.left + ox,
        line.top - origin.top + oy + line.height / 2,
      )
    }
    paintPseudo(ctx, node, '::after', x, y)
    ctx.restore()

    for (const child of node.children) walk(child)
  }
  walk(root)
}

function boxH(srcA: Uint8ClampedArray, dstA: Uint8ClampedArray, w: number, h: number, r: number) {
  const inv = 1 / (2 * r + 1)
  for (let y = 0; y < h; y++) {
    const base = y * w * 4
    let sr = 0
    let sg = 0
    let sb = 0
    let sa = 0
    for (let x = 0; x <= r && x < w; x++) {
      const i = base + x * 4
      sr += srcA[i]!
      sg += srcA[i + 1]!
      sb += srcA[i + 2]!
      sa += srcA[i + 3]!
    }
    for (let x = 0; x < w; x++) {
      const o = base + x * 4
      dstA[o] = sr * inv
      dstA[o + 1] = sg * inv
      dstA[o + 2] = sb * inv
      dstA[o + 3] = sa * inv
      const xa = x + r + 1
      if (xa < w) {
        const ia = base + xa * 4
        sr += srcA[ia]!
        sg += srcA[ia + 1]!
        sb += srcA[ia + 2]!
        sa += srcA[ia + 3]!
      }
      const xs = x - r
      if (xs >= 0) {
        const is = base + xs * 4
        sr -= srcA[is]!
        sg -= srcA[is + 1]!
        sb -= srcA[is + 2]!
        sa -= srcA[is + 3]!
      }
    }
  }
}

function boxV(
  srcA: Uint8ClampedArray,
  dstA: Uint8ClampedArray,
  w: number,
  h: number,
  r: number,
  straight: boolean,
) {
  const stride = w * 4
  const inv = 1 / (2 * r + 1)
  for (let x = 0; x < w; x++) {
    const base = x * 4
    let sr = 0
    let sg = 0
    let sb = 0
    let sa = 0
    for (let y = 0; y <= r && y < h; y++) {
      const i = base + y * stride
      sr += srcA[i]!
      sg += srcA[i + 1]!
      sb += srcA[i + 2]!
      sa += srcA[i + 3]!
    }
    for (let y = 0; y < h; y++) {
      const o = base + y * stride
      const aOut = sa * inv
      if (straight && aOut > 0.5 && aOut < 254.6) {
        const k = 255 / aOut
        dstA[o] = sr * inv * k
        dstA[o + 1] = sg * inv * k
        dstA[o + 2] = sb * inv * k
      } else {
        dstA[o] = sr * inv
        dstA[o + 1] = sg * inv
        dstA[o + 2] = sb * inv
      }
      dstA[o + 3] = aOut
      const ya = y + r + 1
      if (ya < h) {
        const ia = base + ya * stride
        sr += srcA[ia]!
        sg += srcA[ia + 1]!
        sb += srcA[ia + 2]!
        sa += srcA[ia + 3]!
      }
      const ys = y - r
      if (ys >= 0) {
        const is = base + ys * stride
        sr -= srcA[is]!
        sg -= srcA[is + 1]!
        sb -= srcA[is + 2]!
        sa -= srcA[is + 3]!
      }
    }
  }
}

export type DissolveOptions = { onComplete?: () => void }

export function dissolve(el: HTMLElement, { onComplete }: DissolveOptions = {}) {
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
    onComplete?.()
    return
  }

  const durMs = readNum('--smoky-dur', 550)
  const g = readNum('--smoky-gravity', 150)
  const warp = readNum('--smoky-warp', 30)
  const warpDurRaw = readNum('--smoky-warp-dur', 0)
  const warpDurMs = warpDurRaw > 0 ? warpDurRaw : durMs
  const maxBlur = readNum('--smoky-blur', 12)
  const sway = readNum('--smoky-sway', 0)
  const spin = readNum('--smoky-spin', 3)
  const churn = readNum('--smoky-churn', 30)
  const spread = readNum('--smoky-spread', 0)
  const grain = readNum('--smoky-grain', 28)
  const warpEase = makeEaseSampler(readStr('--smoky-warp-ease'))
  const blurEase = makeEaseSampler(readStr('--smoky-blur-ease'))
  const gravityEase = makeEaseSampler(readStr('--smoky-gravity-ease'))
  const dissolveEase = makeEaseSampler(readStr('--smoky-dissolve-ease'))

  const dpr = Math.min(window.devicePixelRatio || 1, 2)
  const rect = el.getBoundingClientRect()
  const cardW = rect.width
  const cardH = rect.height
  const pad = Math.min(Math.ceil(warp / 2 + maxBlur * 2) + 6, 80)
  const padDev = Math.round(pad * dpr)
  const snapW = Math.max(1, Math.round(cardW * dpr))
  const snapH = Math.max(1, Math.round(cardH * dpr))
  const workW = snapW + padDev * 2
  const workH = snapH + padDev * 2

  const canvas = document.createElement('canvas')
  canvas.width = workW
  canvas.height = workH
  canvas.setAttribute('aria-hidden', 'true')
  canvas.style.cssText = `position:fixed;left:${rect.left - pad}px;top:${rect.top - pad}px;width:${cardW + pad * 2}px;height:${cardH + pad * 2}px;pointer-events:none;z-index:200;will-change:transform,opacity`
  const ctx = canvas.getContext('2d')
  if (!ctx) {
    onComplete?.()
    return
  }
  ctx.imageSmoothingQuality = 'high'

  const snap = document.createElement('canvas')
  snap.width = snapW
  snap.height = snapH
  const sc = snap.getContext('2d')
  if (!sc) {
    onComplete?.()
    return
  }
  sc.setTransform(dpr, 0, 0, dpr, 0, 0)
  paint(sc, el, 0, 0)

  const sd = sc.getImageData(0, 0, snapW, snapH).data
  const snapPre = new Uint8ClampedArray(sd.length)
  for (let i = 0; i < sd.length; i += 4) {
    const aP = sd[i + 3]!
    snapPre[i] = (sd[i]! * aP) / 255
    snapPre[i + 1] = (sd[i + 1]! * aP) / 255
    snapPre[i + 2] = (sd[i + 2]! * aP) / 255
    snapPre[i + 3] = aP
  }

  const workHalf = document.createElement('canvas')
  const wW2 = Math.ceil(workW / 2)
  const wH2 = Math.ceil(workH / 2)
  workHalf.width = wW2
  workHalf.height = wH2
  const whctx = workHalf.getContext('2d')!
  const workData = ctx.createImageData(workW, workH)
  const halfData = whctx.createImageData(wW2, wH2)
  const blurTmp = new Uint8ClampedArray(halfData.data.length)

  const LAT = 4
  const latW = Math.ceil(workW / LAT) + 2
  const latH = Math.ceil(workH / LAT) + 2
  const latDX = new Float32Array(latW * latH)
  const latDY = new Float32Array(latW * latH)

  function remap(dstArr: Uint8ClampedArray, dw: number, dh: number, s: number, straight: boolean) {
    const src = snapPre
    const invLat = 1 / LAT
    let di = 0
    for (let yD = 0; yD < dh; yD++) {
      const yF = yD * s
      const gy = yF * invLat
      const gy0 = gy | 0
      const fy = gy - gy0
      const row0 = gy0 * latW
      const row1 = row0 + latW
      for (let xD = 0; xD < dw; xD++, di += 4) {
        const xF = xD * s
        const gx = xF * invLat
        const gx0 = gx | 0
        const fx = gx - gx0
        const a = row0 + gx0
        const b = row1 + gx0
        const dxv =
          (latDX[a]! + (latDX[a + 1]! - latDX[a]!) * fx) * (1 - fy) +
          (latDX[b]! + (latDX[b + 1]! - latDX[b]!) * fx) * fy
        const dyv =
          (latDY[a]! + (latDY[a + 1]! - latDY[a]!) * fx) * (1 - fy) +
          (latDY[b]! + (latDY[b + 1]! - latDY[b]!) * fx) * fy
        const sxf = xF - padDev + dxv
        const syf = yF - padDev + dyv
        const sx0 = Math.floor(sxf)
        const sy0 = Math.floor(syf)
        if (sx0 < -1 || sx0 > snapW - 1 || sy0 < -1 || sy0 > snapH - 1) {

          dstArr[di] = 0
          dstArr[di + 1] = 0
          dstArr[di + 2] = 0
          dstArr[di + 3] = 0
          continue
        }
        const u = sxf - sx0
        const v = syf - sy0
        let rC = 0
        let gC = 0
        let bC = 0
        let aC = 0
        for (const [ox2, oy2, w] of [
          [0, 0, (1 - u) * (1 - v)],
          [1, 0, u * (1 - v)],
          [0, 1, (1 - u) * v],
          [1, 1, u * v],
        ] as const) {
          const sx = sx0 + ox2
          const sy = sy0 + oy2
          if (sx < 0 || sx >= snapW || sy < 0 || sy >= snapH) continue
          const si = (sy * snapW + sx) * 4
          rC += src[si]! * w
          gC += src[si + 1]! * w
          bC += src[si + 2]! * w
          aC += src[si + 3]! * w
        }
        if (straight && aC > 0.5 && aC < 254.6) {
          const k = 255 / aC
          rC *= k
          gC *= k
          bC *= k
        }
        dstArr[di] = rC
        dstArr[di + 1] = gC
        dstArr[di + 2] = bC
        dstArr[di + 3] = aC
      }
    }
  }

  const N = 64
  const noiseR = new Float32Array(N * N)
  const noiseG = new Float32Array(N * N)
  let seed = 4
  for (let i = 0; i < N * N; i++) {
    seed = (seed * 1664525 + 1013904223) >>> 0
    noiseR[i] = seed / 2147483648 - 1
    seed = (seed * 1664525 + 1013904223) >>> 0
    noiseG[i] = seed / 2147483648 - 1
  }
  const gridAt = (gArr: Float32Array, x: number, y: number) => {
    const xi = Math.floor(x)
    const yi = Math.floor(y)
    let fx = x - xi
    let fy = y - yi
    fx = fx * fx * (3 - 2 * fx)
    fy = fy * fy * (3 - 2 * fy)
    const x0 = ((xi % N) + N) % N
    const x1 = (x0 + 1) % N
    const y0 = ((yi % N) + N) % N
    const y1 = (y0 + 1) % N
    const top = gArr[y0 * N + x0]! + (gArr[y0 * N + x1]! - gArr[y0 * N + x0]!) * fx
    const bot = gArr[y1 * N + x0]! + (gArr[y1 * N + x1]! - gArr[y1 * N + x0]!) * fx
    return top + (bot - top) * fy
  }
  const noise2 = (gArr: Float32Array, px: number, py: number) =>
    (gridAt(gArr, px / grain, py / grain) +
      0.5 * gridAt(gArr, (px / grain) * 2 + 37.7, (py / grain) * 2 + 11.3)) /
    1.5

  el.style.visibility = 'hidden'
  document.body.appendChild(canvas)
  const t0 = performance.now()
  let frame = 0

  const tick = (now: number) => {
    const t = (now - t0) / 1000

    const rawP = Math.min((now - t0) / Math.max(durMs, 1), 1)
    const p = dissolveEase(rawP)

    const teff = gravityEase(p) * (durMs / 1000)
    const fallY = 0.5 * g * teff * teff
    const swayX = Math.sin(t * 5) * sway * p
    const pw = Math.min((now - t0) / Math.max(warpDurMs, 1), 1)
    const dispScale = warp * warpEase(pw)
    const blur = maxBlur * blurEase(p)
    const alpha = 1 - p ** 1.6
    const driftY = churn * t
    const driftX = Math.sin(t * 3.2) * churn * 0.3

    if (frame % 2 === 0 || rawP >= 1) {
      const halfDev = (dispScale / 2) * dpr
      for (let ly = 0; ly < latH; ly++) {
        const py = (ly * LAT - padDev) / dpr
        for (let lx = 0; lx < latW; lx++) {
          const px = (lx * LAT - padDev) / dpr
          const li = ly * latW + lx
          latDX[li] = halfDev * noise2(noiseR, px - driftX, py - driftY)
          latDY[li] = halfDev * noise2(noiseG, px - driftX, py - driftY)
        }
      }
      const rBox = blur > 0.3 ? Math.round(blur * dpr * 1.22) : 0
      if (rBox >= 2) {
        remap(halfData.data, wW2, wH2, 2, false)
        const rHalf = Math.max(1, Math.round(rBox / 2))
        boxH(halfData.data, blurTmp, wW2, wH2, rHalf)
        boxH(blurTmp, halfData.data, wW2, wH2, rHalf)
        boxV(halfData.data, blurTmp, wW2, wH2, rHalf, false)
        boxV(blurTmp, halfData.data, wW2, wH2, rHalf, true)
        whctx.putImageData(halfData, 0, 0)
        ctx.clearRect(0, 0, workW, workH)
        ctx.drawImage(workHalf, 0, 0, wW2, wH2, 0, 0, workW, workH)
      } else {
        remap(workData.data, workW, workH, 1, true)
        ctx.putImageData(workData, 0, 0)
      }
    }
    frame++

    canvas.style.transform = `translate(${swayX.toFixed(1)}px, ${fallY.toFixed(1)}px) rotate(${(spin * p).toFixed(2)}deg) scale(${(1 + (spread / 100) * p).toFixed(3)})`
    canvas.style.opacity = alpha.toFixed(3)

    if (rawP < 1) {
      requestAnimationFrame(tick)
      return
    }
    canvas.remove()
    onComplete?.()
  }
  requestAnimationFrame(tick)
}
